cd /work/workspace && python3 - <<'EOF'
import csv
open_bal={}
for r in csv.DictReader(open('documents/balancete_abertura.csv')):
    open_bal[r['conta']]=float(r['debito'])-float(r['credito'])
mov={}
for r in csv.DictReader(open('documents/mes_01/razao.csv')):
    if r['ref']=='ABERT': continue
    mov[r['conta']]=mov.get(r['conta'],0)+float(r['debito'] or 0)-float(r['credito'] or 0)
close={}
for r in csv.DictReader(open('documents/mes_01/balancete.csv')):
    close[r['conta']]=float(r['debito'])-float(r['credito'])
for k in sorted(set(open_bal)|set(mov)|set(close)):
    calc=open_bal.get(k,0)+mov.get(k,0)
    print(k, calc, close.get(k), "OK" if abs(calc-close.get(k,0))<0.01 else "DIVERGE")
EOF

